{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Project",
  "description": "The whole video, as a single declarative document.\n\nField order is canonical key order (ADR-0041), and matches the committed fixture\nexactly. `loop` is the one field whose position no ADR states — ADR-0062 introduced it\nand ADR-0041's rule hands the position to the introducing ADR, which did not take it.\nIt is placed next to `duration` because that is the field it talks about: `loop: true`\nasserts that `duration` connects back to `0`. Recorded rather than decided silently.",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "frame": {
      "$ref": "#/$defs/Frame"
    },
    "fps": {
      "type": "integer",
      "format": "int64"
    },
    "background": {
      "$ref": "#/$defs/Colour"
    },
    "duration": {
      "type": "integer",
      "format": "int64"
    },
    "loop": {
      "type": "boolean",
      "description": "ADR-0062. Default `false`/absent; affects nothing but one `validate` check, and\nMontagent writes no container-level loop metadata."
    },
    "output": {
      "type": "string"
    },
    "fonts": {
      "type": "object",
      "additionalProperties": {
        "type": "array",
        "items": {
          "$ref": "#/$defs/FontFile"
        }
      }
    },
    "fontVendor": {
      "type": "object",
      "additionalProperties": {
        "$ref": "#/$defs/FontAttestation"
      }
    },
    "tracks": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/Track"
      }
    }
  },
  "required": [
    "frame",
    "fps",
    "tracks"
  ],
  "$defs": {
    "Frame": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "width": {
          "type": "integer",
          "format": "int64"
        },
        "height": {
          "type": "integer",
          "format": "int64"
        }
      },
      "required": [
        "width",
        "height"
      ],
      "description": "The project's pixel dimensions."
    },
    "Colour": {
      "type": "string",
      "description": "`#RRGGBB` or `#RRGGBBAA`, uppercase, and nothing else."
    },
    "FontFile": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "file": {
          "type": "string"
        },
        "index": {
          "type": "integer",
          "format": "uint32",
          "minimum": 0,
          "description": "For `.ttc` collections. 49 of the fonts in a stock macOS `/System/Library/Fonts`\nare collections, so this is the normal case rather than an exotic one."
        }
      },
      "required": [
        "file"
      ],
      "description": "One entry in a font's ordered fallback chain: always a file path relative to the\nproject, never a system family name (ADR-0007)."
    },
    "FontAttestation": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "licence": {
          "type": "string"
        },
        "source": {
          "type": "string"
        },
        "sha256": {
          "type": "string"
        }
      },
      "required": [
        "licence",
        "source",
        "sha256"
      ],
      "description": "What `fonts vendor` learned about one font file, keyed by that file's path.\n\nADR-0057 put this in its own top-level table rather than inline on each chain entry:\nthe `fonts` table is a *reference* structure and one file may appear under several\nkeys, so inlining would duplicate the same hash and licence at every point of reference\n— and duplicated facts drift the moment one copy is re-vendored and the other is not."
    },
    "Track": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "name": {
          "type": "string"
        },
        "layer": {
          "type": "integer",
          "format": "int64"
        },
        "elements": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/Element"
          }
        }
      },
      "required": [
        "name",
        "layer",
        "elements"
      ],
      "description": "A named container holding elements, with an integer `layer` giving its place in the\nstack.\n\nA track supplies *stacking*, never *timing*: it has no start, no duration and no clock\n(ADR-0004). Array order carries no meaning, for timing or for stacking — ADR-0060\nconfirmed a layer tie is never broken by declaration order."
    },
    "Element": {
      "oneOf": [
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "id": {
              "type": "string"
            },
            "type": {
              "type": "string",
              "const": "image"
            },
            "group": {
              "type": "string"
            },
            "start": {
              "type": "integer",
              "format": "int64"
            },
            "end": {
              "type": "integer",
              "format": "int64"
            },
            "layer": {
              "$ref": "#/$defs/Layer"
            },
            "source": {
              "type": "string",
              "description": "Inline, never an asset-table reference (ADR-0002)."
            },
            "x": {
              "$ref": "#/$defs/Animatable"
            },
            "y": {
              "$ref": "#/$defs/Animatable"
            },
            "origin": {
              "$ref": "#/$defs/Origin"
            },
            "width": {
              "type": "integer",
              "format": "int64",
              "description": "Required, never defaulted: the source's dimensions are not in the document, so a\nnatural-size default would make the element's rendered rect unreadable — and it\nwould fail *quietly*, because a centre-cropped photo looks plausible (ADR-0012)."
            },
            "height": {
              "type": "integer",
              "format": "int64"
            },
            "fit": {
              "$ref": "#/$defs/Fit",
              "description": "Required on every element carrying a raster source; omission is a schema error\nnaming the three values (ADR-0015)."
            },
            "clip": {
              "type": "array",
              "items": {
                "type": "integer",
                "format": "int64"
              },
              "minItems": 4,
              "maxItems": 4
            },
            "scale": {
              "$ref": "#/$defs/Animatable2"
            },
            "rotation": {
              "description": "Degrees clockwise, and **never normalised into `[0,360)`** — `1080` is three turns,\nand a writer that wraps it silently renders one third of the motion.",
              "$ref": "#/$defs/Animatable3"
            },
            "opacity": {
              "$ref": "#/$defs/Animatable3"
            },
            "effects": {
              "type": "array",
              "items": {
                "$ref": "#/$defs/Effect"
              }
            }
          },
          "required": [
            "id",
            "type",
            "start",
            "end",
            "source",
            "width",
            "height",
            "fit"
          ],
          "description": "`source, x, y, origin, width, height, fit, clip, scale` — ADR-0041's measured order —\nthen the two transform properties ADR-0012 declares after `scale`, then `effects`."
        },
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "id": {
              "type": "string"
            },
            "type": {
              "type": "string",
              "const": "video"
            },
            "group": {
              "type": "string"
            },
            "start": {
              "type": "integer",
              "format": "int64"
            },
            "end": {
              "type": "integer",
              "format": "int64"
            },
            "layer": {
              "$ref": "#/$defs/Layer"
            },
            "source": {
              "type": "string"
            },
            "source_start": {
              "type": "integer",
              "format": "int64"
            },
            "source_end": {
              "type": "integer",
              "format": "int64"
            },
            "x": {
              "$ref": "#/$defs/Animatable"
            },
            "y": {
              "$ref": "#/$defs/Animatable"
            },
            "origin": {
              "$ref": "#/$defs/Origin"
            },
            "width": {
              "type": "integer",
              "format": "int64"
            },
            "height": {
              "type": "integer",
              "format": "int64"
            },
            "fit": {
              "$ref": "#/$defs/Fit"
            },
            "clip": {
              "type": "array",
              "items": {
                "type": "integer",
                "format": "int64"
              },
              "minItems": 4,
              "maxItems": 4
            },
            "scale": {
              "$ref": "#/$defs/Animatable2"
            },
            "rotation": {
              "$ref": "#/$defs/Animatable3"
            },
            "opacity": {
              "$ref": "#/$defs/Animatable3"
            },
            "speed": {
              "$ref": "#/$defs/Speed"
            },
            "overrun": {
              "$ref": "#/$defs/Overrun"
            },
            "volume": {
              "description": "A video element is one element with intrinsic audio, so its embedded audio reuses\nthis same field and there is no `mute` — `volume: 0` already says silent, including\nat one instant via a keyframe (ADR-0055).",
              "$ref": "#/$defs/Animatable4"
            },
            "effects": {
              "type": "array",
              "items": {
                "$ref": "#/$defs/Effect"
              }
            }
          },
          "required": [
            "id",
            "type",
            "start",
            "end",
            "source",
            "source_start",
            "source_end",
            "width",
            "height",
            "fit"
          ],
          "description": "An image that also has a clock.\n\nADR-0041 has no measured order for `video` — the fixture has no instance — and states\nthat whichever ADR first fixes its full property set fixes its order too. No ADR has,\nso this ticket does, following the two orders that *are* measured: `image`'s visual\nsequence, with `audio`'s `source_start, source_end` in `audio`'s own relative position\ndirectly after `source`, then the fields a video shares with audio."
        },
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "id": {
              "type": "string"
            },
            "type": {
              "type": "string",
              "const": "text"
            },
            "group": {
              "type": "string"
            },
            "start": {
              "type": "integer",
              "format": "int64"
            },
            "end": {
              "type": "integer",
              "format": "int64"
            },
            "layer": {
              "$ref": "#/$defs/Layer"
            },
            "x": {
              "$ref": "#/$defs/Animatable"
            },
            "y": {
              "$ref": "#/$defs/Animatable"
            },
            "origin": {
              "$ref": "#/$defs/Origin"
            },
            "width": {
              "type": "integer",
              "format": "int64",
              "description": "The box the text must fit inside — required, because an omitted `height` would be\nindistinguishable from a decision not to check (ADR-0014). It is a *container\nclaim*, not drawn geometry, which is why a stroke grows into it rather than past it."
            },
            "height": {
              "type": "integer",
              "format": "int64"
            },
            "font": {
              "type": "string",
              "description": "A key into the project's `fonts` table, never a system family name."
            },
            "size": {
              "type": "integer",
              "format": "int64",
              "description": "A literal number. The renderer never chooses a size and never chooses a line break\n(ADR-0007) — the fitted sizes in the fixture came from a pipeline that measured and\nwrote literals, and that loop moves to authoring time rather than disappearing.\n\nAn integer, by ADR-0012's absolute-integer-pixels rule: a size is a length in the\nproject's frame space, like `width` and `height`, and all 22 of the fixture's text\nelements carry one. A float would additionally give every whole size two spellings —\n`55` and `55.0` — which is the ambiguity `center-center` and the `scale` union were\neach retired for."
            },
            "line_height": {
              "type": "number",
              "format": "double",
              "description": "Restricted to one decimal digit, always exactly representable as `n/10`, so the\nblock-height derivation is exact integer arithmetic and never IEEE double\n(ADR-0028). Defaults to `1.2` when omitted."
            },
            "color": {
              "$ref": "#/$defs/Colour"
            },
            "align": {
              "$ref": "#/$defs/Align"
            },
            "runs": {
              "type": "array",
              "items": {
                "$ref": "#/$defs/Run"
              }
            },
            "stroke": {
              "$ref": "#/$defs/Colour"
            },
            "stroke_width": {
              "type": "integer",
              "format": "int64"
            },
            "scale": {
              "$ref": "#/$defs/Animatable2"
            },
            "rotation": {
              "$ref": "#/$defs/Animatable3"
            },
            "opacity": {
              "$ref": "#/$defs/Animatable3"
            },
            "effects": {
              "type": "array",
              "items": {
                "$ref": "#/$defs/Effect"
              }
            }
          },
          "required": [
            "id",
            "type",
            "start",
            "end",
            "width",
            "height",
            "font",
            "size",
            "runs"
          ],
          "description": "`x, y, origin, width, height, font, size, line_height, color, align, runs` — ADR-0041's\nmeasured order — then the paint ADR-0014 adds, the transform properties, and `effects`."
        },
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "id": {
              "type": "string"
            },
            "type": {
              "type": "string",
              "const": "rect"
            },
            "group": {
              "type": "string"
            },
            "start": {
              "type": "integer",
              "format": "int64"
            },
            "end": {
              "type": "integer",
              "format": "int64"
            },
            "layer": {
              "$ref": "#/$defs/Layer"
            },
            "x": {
              "$ref": "#/$defs/Animatable"
            },
            "y": {
              "$ref": "#/$defs/Animatable"
            },
            "origin": {
              "$ref": "#/$defs/Origin"
            },
            "width": {
              "type": "integer",
              "format": "int64"
            },
            "height": {
              "type": "integer",
              "format": "int64"
            },
            "fill": {
              "description": "Optional when a `stroke` is present, giving an outlined shape. A shape with neither\nis a schema error naming both, because an element that deliberately renders nothing\nand an element that forgot its paint must not look alike.",
              "$ref": "#/$defs/Colour"
            },
            "stroke": {
              "description": "On a shape the stroke falls **inside** the declared rect, so a stroked `card-05`\nstill occupies exactly 984×169 (ADR-0014).",
              "$ref": "#/$defs/Colour"
            },
            "stroke_width": {
              "type": "integer",
              "format": "int64"
            },
            "radius": {
              "type": "integer",
              "format": "int64",
              "description": "A single integer, defaulting to 0 — one corner radius, not four.\n\nThe fixture is measurably square and the README's *\"rounded cream panel\"* was wrong,\nwhich under ADR-0003's asymmetry is **not** evidence against the field: a rounded\nrectangle is unremarkable in the CapCut/Premiere reference class, and admitting it\nnow costs one clause where admitting it later is a schema change."
            },
            "scale": {
              "$ref": "#/$defs/Animatable2"
            },
            "rotation": {
              "$ref": "#/$defs/Animatable3"
            },
            "opacity": {
              "$ref": "#/$defs/Animatable3"
            },
            "effects": {
              "type": "array",
              "items": {
                "$ref": "#/$defs/Effect"
              }
            }
          },
          "required": [
            "id",
            "type",
            "start",
            "end",
            "width",
            "height"
          ],
          "description": "A rounded or square rectangle.\n\n**`rect` and `ellipse` are two types rather than one with a `shape` discriminator\ninside it** (ADR-0014): ADR-0012 already made the field set a function of `type`, so a\nsecond narrowing mechanism would add a second, *omissible* one — and a malformed\nellipse missing its discriminator would render as a rect, silently and plausibly, which\nis this format's named failure class.\n\nThey are also two *structs*, and the one field that differs is why: ADR-0014's heading\nis *\"`radius` is a field on `rect`\"*, so `radius` on an ellipse is an unknown key rather\nthan a field that quietly does nothing. An ellipse inscribing its rect has no corners to\nround, and ADR-0007 has ruled twice that *\"a field the renderer cannot honour is worse\nthan no field.\"*\n\nADR-0041's measured order is `x, y, origin, width, height, fill`; the three fields\nADR-0014 adds follow, in the order that ADR's own headings introduce them — `stroke`,\n`stroke_width`, then `radius`. ADR-0041 hands a new field's position to the ADR that\nintroduces it and ADR-0014 did not take it explicitly, so that reading is this\nticket's and is raised as [#274](https://github.com/MBehtemam/Montagent/issues/274)\nrather than left to be discovered from the struct."
        },
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "id": {
              "type": "string"
            },
            "type": {
              "type": "string",
              "const": "ellipse"
            },
            "group": {
              "type": "string"
            },
            "start": {
              "type": "integer",
              "format": "int64"
            },
            "end": {
              "type": "integer",
              "format": "int64"
            },
            "layer": {
              "$ref": "#/$defs/Layer"
            },
            "x": {
              "$ref": "#/$defs/Animatable"
            },
            "y": {
              "$ref": "#/$defs/Animatable"
            },
            "origin": {
              "$ref": "#/$defs/Origin"
            },
            "width": {
              "type": "integer",
              "format": "int64"
            },
            "height": {
              "type": "integer",
              "format": "int64"
            },
            "fill": {
              "description": "Optional when a `stroke` is present, giving an outlined shape. A shape with neither\nis a schema error naming both, because an element that deliberately renders nothing\nand an element that forgot its paint must not look alike.",
              "$ref": "#/$defs/Colour"
            },
            "stroke": {
              "description": "On a shape the stroke falls **inside** the declared rect, so a stroked `card-05`\nstill occupies exactly 984×169 (ADR-0014).",
              "$ref": "#/$defs/Colour"
            },
            "stroke_width": {
              "type": "integer",
              "format": "int64"
            },
            "scale": {
              "$ref": "#/$defs/Animatable2"
            },
            "rotation": {
              "$ref": "#/$defs/Animatable3"
            },
            "opacity": {
              "$ref": "#/$defs/Animatable3"
            },
            "effects": {
              "type": "array",
              "items": {
                "$ref": "#/$defs/Effect"
              }
            }
          },
          "required": [
            "id",
            "type",
            "start",
            "end",
            "width",
            "height"
          ],
          "description": "An ellipse inscribing its declared rect — which is exactly what distinguishes it from\nthe point-list shapes ADR-0014 rejected: it needs no new placement rule.\n\n[`Rect`]'s field set minus `radius`; see that type for why the two are separate.\n\n**Contradicts a parenthetical in [ADR-0041], and says so rather than overriding it\nsilently** (`docs/agents/domain.md`). That ADR writes *\"`video` and `ellipse` have no\ncommitted instance to measure yet; per the rule above, whichever ADR first fixes their\nfull property set (they inherit `image`'s and `rect`'s shape respectively) fixes their\norder too\"* — and the shape an ellipse would inherit now carries `radius`. The same\nsentence is what resolves it: the ADR that fixes a type's full property set fixes it,\nand that ADR is ADR-0014, whose own heading is *\"`radius` is a field on `rect`\"*. So the\ninheritance holds for every field ADR-0041 measured and stops at the one ADR-0014 gave\nto `rect` alone. Raised as [#274](https://github.com/MBehtemam/Montagent/issues/274)\nrather than left as a discrepancy a reader has to reconcile.\n\n[ADR-0041]: ../../../../docs/adr/0041-canonical-key-order-is-schema-order-validate-checks-it-fmt-splits.md"
        },
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "id": {
              "type": "string"
            },
            "type": {
              "type": "string",
              "const": "audio"
            },
            "group": {
              "type": "string"
            },
            "start": {
              "type": "integer",
              "format": "int64"
            },
            "end": {
              "type": "integer",
              "format": "int64"
            },
            "layer": {
              "$ref": "#/$defs/Layer"
            },
            "source": {
              "type": "string"
            },
            "source_start": {
              "type": "integer",
              "format": "int64"
            },
            "source_end": {
              "type": "integer",
              "format": "int64"
            },
            "speed": {
              "$ref": "#/$defs/Speed"
            },
            "overrun": {
              "$ref": "#/$defs/AudioOverrun"
            },
            "volume": {
              "$ref": "#/$defs/Animatable4"
            }
          },
          "required": [
            "id",
            "type",
            "start",
            "end",
            "source",
            "source_start",
            "source_end"
          ],
          "description": "`source, source_start, source_end` — ADR-0041's measured order — then the fields the\nfixture appends after a type's core set.\n\nAn audio element carries no transform: `x` on it is a schema error naming the\nreplacement, and the specific trap is `opacity`, which an agent will write meaning\nvolume and which would fade nothing, forever (ADR-0012)."
        },
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "id": {
              "type": "string"
            },
            "type": {
              "type": "string",
              "const": "transition"
            },
            "group": {
              "type": "string"
            },
            "start": {
              "type": "integer",
              "format": "int64"
            },
            "end": {
              "type": "integer",
              "format": "int64"
            },
            "layer": {
              "$ref": "#/$defs/Layer"
            },
            "kind": {
              "$ref": "#/$defs/TransitionKind",
              "description": "`crossfade` is the whole v1 vocabulary. Wipe, slide and push are deferred — not\nbecause they are unwanted but because reference-class ubiquity is no evidence for\nhow they parameterize, and freezing a closed-vocabulary member on a guess is the\ntrap ADR-0040 avoided with colour filter."
            },
            "from": {
              "type": "string"
            },
            "to": {
              "type": "string"
            }
          },
          "required": [
            "id",
            "type",
            "start",
            "end",
            "kind",
            "from",
            "to"
          ],
          "description": "A transition is its own element type, with its own time range and two id references —\nnot a property on either bridged element, which would create an unprincipled ownership\nquestion, and not an effect, which is element-local by construction (ADR-0059).\n\nADR-0059 names *\"two id references\"* without naming the fields. This ticket calls them\n`from` and `to`, and records that as a spelling the ADR series may want to ratify."
        }
      ],
      "description": "The per-type field set, discriminated by `type`.\n\nADR-0012: the field set is a **function of `type`** — *\"`x` on an audio element is a\nschema error naming the replacement\"*, never a silently-ignored field. That is also why\nshapes are sibling types rather than one `shape` type with a discriminator inside it: a\nsecond, omissible discriminator would let a malformed ellipse render as a rect, silently\nand plausibly (ADR-0014)."
    },
    "Animatable": {
      "anyOf": [
        {
          "type": "integer",
          "format": "int64",
          "description": "Constant for the element's whole life."
        },
        {
          "type": "array",
          "prefixItems": [
            {
              "$ref": "#/$defs/FirstKeyframe"
            }
          ],
          "items": {
            "$ref": "#/$defs/Keyframe"
          },
          "description": "Keyframed. Clamps at both ends (ADR-0012): before the first record the value is the\nfirst value, after the last it is the last, so *\"and then it holds\"* costs no syntax.\nRecords must be written with strictly increasing `t` (ADR-0082) — array order is\nclock order.",
          "minItems": 1
        }
      ],
